using HelpDeskPro.Api.Models; using Microsoft.EntityFrameworkCore;
namespace HelpDeskPro.Api.Data;
public class AppDbContext:DbContext { public AppDbContext(DbContextOptions<AppDbContext> o):base(o){} public DbSet<User> Users=>Set<User>(); public DbSet<Department> Departments=>Set<Department>(); public DbSet<Ticket> Tickets=>Set<Ticket>(); public DbSet<TicketComment> TicketComments=>Set<TicketComment>(); public DbSet<TicketAttachment> TicketAttachments=>Set<TicketAttachment>(); public DbSet<KnowledgeArticle> KnowledgeArticles=>Set<KnowledgeArticle>(); public DbSet<ActivityLog> ActivityLogs=>Set<ActivityLog>(); public DbSet<Notification> Notifications=>Set<Notification>(); protected override void OnModelCreating(ModelBuilder b){ b.Entity<User>().HasIndex(x=>x.Email).IsUnique(); b.Entity<Ticket>().HasOne(x=>x.CreatedBy).WithMany(x=>x.CreatedTickets).HasForeignKey(x=>x.CreatedById).OnDelete(DeleteBehavior.Restrict); b.Entity<Ticket>().HasOne(x=>x.AssignedTo).WithMany(x=>x.AssignedTickets).HasForeignKey(x=>x.AssignedToId).OnDelete(DeleteBehavior.SetNull); b.Entity<TicketComment>().HasOne(x=>x.User).WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Restrict); b.Entity<TicketAttachment>().HasOne(x=>x.Ticket).WithMany(x=>x.Attachments).HasForeignKey(x=>x.TicketId).OnDelete(DeleteBehavior.Cascade); } }
